#include <cstdint>
struct Mod {
 std::uint32_t v=0;
 Mod()=default;
 Mod(std::int64_t x) { x%=998244353; if(x<0)x+=998244353;v=static_cast<std::uint32_t>(x); }
 Mod& operator+=(Mod x){v+=x.v;if(v>=998244353)v-=998244353;return *this;}
 friend Mod operator+(Mod a,Mod b){return a+=b;}
 friend Mod operator-(Mod a,Mod b){return Mod(static_cast<std::int64_t>(a.v)-b.v);}
 friend Mod operator-(Mod a){return Mod(-static_cast<std::int64_t>(a.v));}
 friend bool operator==(Mod,Mod)=default;
};
struct Ring {
 std::int64_t v=0;
 Ring()=default;Ring(std::int64_t x):v(x){}
 Ring& operator+=(Ring b){v+=b.v;return *this;}
 friend Ring operator+(Ring a,Ring b){return a+=b;}
 friend Ring operator-(Ring a,Ring b){return Ring(a.v-b.v);}
 friend Ring operator-(Ring a){return Ring(-a.v);}
 friend bool operator==(Ring,Ring)=default;
};
template<class T>std::uint64_t checksum_value(const T&x){if constexpr(requires{x.v;})return static_cast<std::uint64_t>(x.v);else return static_cast<std::uint64_t>(x);}

