#include <random>
using T=VALUE;
int main(int argc,char**argv){
 if(argc!=6)return 2;const int n=std::atoi(argv[1]),width=std::atoi(argv[2]),shape=std::atoi(argv[3]),warm=std::atoi(argv[4]),reps=std::atoi(argv[5]);
 UnionFindW<T> uf(n);std::vector<int>ids(n);std::iota(ids.begin(),ids.end(),0);
 if(shape==2){std::mt19937 rng(18763);std::shuffle(ids.begin(),ids.end(),rng);}
 if(shape==3){std::vector<int>logical(n);std::iota(logical.begin(),logical.end(),0);std::stable_sort(logical.begin(),logical.end(),[](unsigned a,unsigned b){return std::popcount(a)>std::popcount(b);});for(int i=0;i<n;++i)ids[logical[i]]=i;}
 for(int first=0;first<n;first+=width){const int last=std::min(n,first+width);if(shape==1){for(int j=first+1;j<last;++j)uf.unite(ids[first],ids[j],T(j-first));}else for(int step=1;step<width;step*=2)for(int i=first;i+step<last;i+=2*step)uf.unite(ids[i],ids[i+step],T(step));}
 std::vector<UnionFindW<T>> copies;if(warm){(void)uf.groups();}else{copies.reserve(reps);for(int i=0;i<reps;++i)copies.push_back(uf);}
 std::uint64_t sum=0;const auto begin=std::clock();
 for(int rep=0;rep<reps;++rep){auto&state=warm?uf:copies[rep];auto gs=state.groups();sum+=gs.size();for(const auto&g:gs){sum+=g.size();for(int v:g)sum+=v;}}
 const auto elapsed=std::clock()-begin;
 auto&state=warm?uf:copies[0];for(int v=0;v<n;v+=std::max(1,n/1000)){const int first=(v/width)*width;const auto d=state.try_diff(ids[first],ids[v]);if(!d||checksum_value(*d)!=checksum_value(T(v-first)))return 3;}
 std::printf("%ju %ju\n",static_cast<std::uintmax_t>(elapsed)*1000000000/CLOCKS_PER_SEC,static_cast<std::uintmax_t>(sum));
}

