from pathlib import Path
import subprocess,json,hashlib,random,statistics,shutil
p=Path(__file__).parent;o=p/'root_screen';o.mkdir(exist_ok=True);cs={'gcc':['/usr/bin/g++'],'clang':['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']};vs={'baseline':p/'baseline/library.hpp','control':p/'baseline/library.hpp','iterative':p/'iterative.hpp'};types={'int64':'std::int64_t','mod':'Mod','ring':'Ring'};modes=[2,4,5,10,11,13,14,15];builds=[]
for cc,c in cs.items():
 for typ,t in types.items():
  for mode in modes:
   for v,h in vs.items():
    out=o/f'{cc}-{typ}-{mode}-{v}'
    if v=='control':shutil.copyfile(o/f'{cc}-{typ}-{mode}-baseline',out);continue
    cmd=['taskset','-c','4',*c,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DMODE={mode}',f'-DVALUE={t}',f'-DSOURCE="{h}"',str(p/'isolated_api.cpp'),'-o',str(out)];a=subprocess.run(cmd,capture_output=True,text=True);assert a.returncode==0,a.stderr;builds.append(dict(cc=cc,type=typ,mode=mode,variant=v,source_sha256=hashlib.sha256(h.read_bytes()).hexdigest(),command=cmd))
 print('built root',cc,flush=True)
(o/'builds.json').write_text(json.dumps(builds,indent=2));raw=[];rng=random.Random(5544321)
for cc in cs:
 for typ in types:
  for n in [32768,524288]:
   reps=8 if n==32768 else 2
   for mode in modes:
    sums=set()
    for rep in range(7):
     order=list(vs);rng.shuffle(order)
     for v in order:
      active=o/'active';shutil.copyfile(o/f'{cc}-{typ}-{mode}-{v}',active);active.chmod(0o755);a=subprocess.run(['taskset','-c','12',str(active),str(n),str(mode),str(reps)],capture_output=True,text=True);assert a.returncode==0,(cc,typ,n,mode,v,a.stderr);ns,s=map(int,a.stdout.split());sums.add(s);raw.append(dict(cc=cc,type=typ,n=n,mode=mode,loops=reps,rep=rep,variant=v,ns=ns,checksum=s))
    assert len(sums)==1,(cc,typ,n,mode,sums)
   print('root measured',cc,typ,n,flush=True)
(o/'raw.json').write_text(json.dumps(raw,indent=2));summary=[]
for cc,typ,n,mode in sorted({(x['cc'],x['type'],x['n'],x['mode'])for x in raw}):
 med={v:statistics.median(x['ns']for x in raw if x['cc']==cc and x['type']==typ and x['n']==n and x['mode']==mode and x['variant']==v)for v in vs};summary.append(dict(cc=cc,type=typ,n=n,mode=mode,median_ns=med,ratios={v:med[v]/max(med['baseline'],1)for v in vs}))
(o/'summary.json').write_text(json.dumps(summary,indent=2));print('ROOT DONE',len(raw),flush=True)

