if '--build-only'in sys.argv:raise SystemExit
raw=[];rng=random.Random(765414)
for cc in cs:
 for typ in types:
  for n in [32769,524289]:
   loops=4 if n<100000 else 1
   for width in [16,256,n]:
    for shape in [0,2,3]:
     for warm in [0,1]:
      sums=set()
      for rep in range(3):
       order=list(vs);rng.shuffle(order)
       for v in order:
        active=o/'active';shutil.copyfile(o/f'{cc}-{typ}-{v}',active);active.chmod(0o755);cmd=['taskset','-c','12',str(active),str(n),str(width),str(shape),str(warm),str(loops)];a=subprocess.run(cmd,capture_output=True,text=True);assert a.returncode==0,(cc,typ,n,width,shape,warm,v,a.stderr);ns,s=map(int,a.stdout.split());sums.add(s);raw.append(dict(cc=cc,type=typ,n=n,width=width,shape=shape,warm=warm,loops=loops,rep=rep,variant=v,ns=ns,checksum=s))
      assert len(sums)==1
   print('groups measured',cc,typ,n,flush=True)
(o/'raw.json').write_text(json.dumps(raw,indent=2));summary=[]
for cc,typ,n,width,shape,warm in sorted({(x['cc'],x['type'],x['n'],x['width'],x['shape'],x['warm'])for x in raw}):
 med={v:statistics.median(x['ns']for x in raw if x['cc']==cc and x['type']==typ and x['n']==n and x['width']==width and x['shape']==shape and x['warm']==warm and x['variant']==v)for v in vs};summary.append(dict(cc=cc,type=typ,n=n,width=width,shape=shape,warm=warm,median_ns=med,ratios={v:med[v]/max(med['baseline'],1)for v in vs}))
(o/'summary.json').write_text(json.dumps(summary,indent=2));print('GROUPS DONE',len(raw),flush=True)

