from pathlib import Path
import subprocess,json,hashlib,shutil
p=Path(__file__).parent;o=p/'single_groups';o.mkdir(exist_ok=True);cs={'gcc152':['/usr/bin/g++'],'gcc152native':['/usr/bin/g++','-march=native'],'gcc153':['/usr/local/bin/g++'],'clang':['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'],'clangnative':['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15','-march=native']};types={'int64':'std::int64_t','mod':'Mod'};builds=[];identity=[]
for cc,c in cs.items():
 for typ,t in types.items():
  for v in ['baseline','control','avx']:
   shutil.copyfile(p/'release_groups'/f'{cc}-{typ}-{v}',o/f'{cc}-{typ}-{v}')
  out=o/f'{cc}-{typ}-known';cmd=['taskset','-c','4',*c,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DVALUE={t}',f'-DSOURCE="{p/"single_known.hpp"}"',str(p/'groups_bench.cpp'),'-o',str(out)];a=subprocess.run(cmd,capture_output=True,text=True);assert a.returncode==0,a.stderr;builds.append(dict(cc=cc,type=typ,source_sha256=hashlib.sha256((p/'single_known.hpp').read_bytes()).hexdigest(),command=cmd))
  hs={}
  for v in ['avx','known']:
   exe=o/f'{cc}-{typ}-{v}';sec=Path(str(exe)+'.text');subprocess.run(['objcopy','--dump-section',f'.text={sec}',str(exe)],check=True);hs[v]=hashlib.sha256(sec.read_bytes()).hexdigest()
  identity.append(dict(cc=cc,type=typ,text_sha256=hs,identical=hs['avx']==hs['known']))
 print('single built',cc,flush=True)
(o/'builds.json').write_text(json.dumps(builds,indent=2));(o/'identity.json').write_text(json.dumps(identity,indent=2))

